INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES
('eca87480-88e7-4490-b7a7-5e501edae0a7', '21feff02-016d-46e2-bb9d-c27495133b1b', '77. óra: Törtrész', 'Törtrész kiszámítása és kapcsolata az egyenes arányossággal.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "bc65b14e-8dd2-4e3a-966d-e6d14e91dd51", "text": "Hogyan számítjuk ki egy mennyiség 3/5 részét?", "type": "multiple-choice", "options": [{"id": "b1ee9672-02e7-4092-82a6-a11ddb7e6d2a", "text": "Elosztjuk 5-tel és megszorozzuk 3-mal (vagy megszorozzuk 3/5-tel)", "isCorrect": true}, {"id": "72a8283f-a4d1-4d63-a9f1-67825aa790de", "text": "Megszorozzuk 5-tel és elosztjuk 3-mal", "isCorrect": false}, {"id": "7a3e21be-e93c-4c43-93d9-f53c5f962d50", "text": "Hozzáadunk 3/5-öt", "isCorrect": false}, {"id": "ec69935e-ea38-440f-969e-6dde22a1b830", "text": "Kivonunk 3/5-öt", "isCorrect": false}], "timeLimit": 15}, {"id": "ae02f5e9-a9fe-4e02-8424-04e5c5a1c51f", "text": "Mennyi 80-nak a 3/4 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "ad14cd03-ca2c-4e0f-bfd4-f3c8f8f7d45f", "text": "Mennyi 150-nek a 2/3 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "ebf56f1b-66d6-4e04-8d8b-4161ab78e80c", "text": "A törtrész kiszámítása egyenesen arányos a megadott tört nagyságával.", "type": "true-false", "options": [{"id": "2b664c15-ba23-4e08-af6a-73d337265918", "text": "Igaz", "isCorrect": true}, {"id": "f9a5cc93-cfcd-419b-af3c-495c513a1b03", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f70959c9-d111-42f5-9d64-eac15d1ce885", "text": "Mennyi 200-nak az 1/10 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "176b2731-852d-45a7-bca9-0a607f19a6c6", "text": "Ha egy mennyiség 1/2 része 30, mennyi a teljes mennyiség? (30 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "ec180375-6dae-47d8-9503-59e1012a8911", "text": "Mennyi 90-nek a 4/9 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}]'::jsonb, true, NOW()),
('5ab0d4df-0cdb-412d-892d-57db6a3d9455', '21feff02-016d-46e2-bb9d-c27495133b1b', '78. óra: Feladatmegoldás', 'Összetett feladatok megoldása törtrész kiszámításával.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "747bb026-4e5f-4cd8-9175-a7ec91943ac0", "text": "Egy 600 oldalú könyvnek elolvastuk a 3/5 részét. Hány oldalt olvastunk el?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "cb9f2993-7d91-49c3-b0fb-c0481ba1d32f", "text": "Egy 600 oldalú könyvnek elolvastuk a 3/5 részét. Hány oldal van még hátra? (600 - 360)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "240"}, {"id": "19e84f8c-9a2e-4bc5-a966-386c212de7f1", "text": "Kati zsebpénze 4000 Ft. Elköltötte a 3/8 részét. Hány Ft-ot költött el? (4000 * 3/8)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1500"}, {"id": "f19b7ee0-1d97-489d-abb9-c9e91361c60e", "text": "Kati zsebpénze 4000 Ft. Elköltötte a 3/8 részét. Hány Ft-ja maradt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2500"}, {"id": "3bacfb83-34bf-4c23-a2a1-76a94693cdd5", "text": "Ha a törtrész kiszámítása után a maradékot keresük, a teljesből kivonjuk a törtrészt.", "type": "true-false", "options": [{"id": "71be21c1-4ad6-4fd6-acde-52651e4e43ba", "text": "Igaz", "isCorrect": true}, {"id": "6df46fb3-5e8d-4bfb-af1a-076030e106ed", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4ae09270-4974-4bdc-9a77-c87a15d32082", "text": "Mennyi 120-nak a 5/6 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "25d275b2-a97f-40fb-8aad-8c644424f5b2", "text": "A törtrész kiszámítása fontos a pénzügyi és mindennapi döntésekben.", "type": "true-false", "options": [{"id": "07d04138-39fb-4b3f-af58-7607d1abb74e", "text": "Igaz", "isCorrect": true}, {"id": "665f3fe6-dba1-44d4-b985-d8c66f8d7589", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('d728425a-0b3a-4325-be53-c19886b1f829', '21feff02-016d-46e2-bb9d-c27495133b1b', '79. óra: Számonkérés', 'Számonkérés az arány, egyenes arányosság és törtrész témakörökből (10 kérdés).', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "6c04f9e5-94a0-4cf6-a9cf-64fcfcd8ce6b", "text": "1. Mennyi a 6 : 18 arány egyszerűsített alakja?", "type": "multiple-choice", "options": [{"id": "5b305f7a-564f-4942-b7bf-03b327f9a455", "text": "1 : 3", "isCorrect": true}, {"id": "1d756573-85fe-4bca-9ed1-9f186cdf0447", "text": "1 : 2", "isCorrect": false}, {"id": "fa92ca17-8de6-4570-8034-98e867696830", "text": "3 : 1", "isCorrect": false}, {"id": "d7bbcbc6-30c5-460f-9d21-9648bb9dbf19", "text": "2 : 3", "isCorrect": false}], "timeLimit": 15}, {"id": "a3f3524c-ffa4-4e04-8f52-62c85b13c846", "text": "2. Ossz el 400 Ft-ot 1 : 3 arányban! Hány Ft a kisebbik rész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "8a3f3de9-207c-407a-89b1-b4a222cb3887", "text": "3. Ossz el 400 Ft-ot 1 : 3 arányban! Hány Ft a nagyobbik rész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "c6cd6757-3681-4869-b999-f210fd75a23e", "text": "4. Ha 3 kg alma 900 Ft, mennyibe kerül 5 kg alma?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1500"}, {"id": "b8d6d0c8-391b-4afe-ac58-d15cd48b5a74", "text": "5. Mennyi 120-nak a 3/4 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "187a7575-df37-4ff7-a171-bf70ec3a5f3e", "text": "6. Az egyenes arányosság grafikonja az origóból induló félegyenes.", "type": "true-false", "options": [{"id": "d173aa9d-5ad0-4fb6-b3fd-70dba6b636b6", "text": "Igaz", "isCorrect": true}, {"id": "e45b0a7a-8d27-4810-84b1-053a07b7d040", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "00bd80e4-7da5-4100-84bf-88fab753edac", "text": "7. Mi a hiányzó szám a sorozatban: 4, 8, 12, 16, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "c808e01e-c190-4b97-9972-7acee6e3ffa5", "text": "8. Ha egy mennyiség 1/3-a 15, mennyi az egész mennyiség?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "45"}, {"id": "eb60f3e7-3d76-4ada-a3b2-d07d93988c9a", "text": "9. Két mennyiség aránya hányados formájában is felírható.", "type": "true-false", "options": [{"id": "5889522a-c920-4eef-b3f4-4970525c1835", "text": "Igaz", "isCorrect": true}, {"id": "bad1ecc7-cc41-4af0-b914-346725ce2eff", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "637c3a3e-7394-4b2e-81da-0ceaee9c85b4", "text": "10. Mennyi 50-nek a 4/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}]'::jsonb, true, NOW()),
('89e4a7fb-a464-494b-bcf4-571d22f9c068', '21feff02-016d-46e2-bb9d-c27495133b1b', '80. óra: Létraverseny I.', 'Versenyszerű feladatmegoldás páros munkában az arányosságok témájában.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "8b40957b-2869-460e-8569-deef7c451b02", "text": "Ha 2 m szalag 400 Ft, mennyibe kerül 10 m szalag?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "f2436556-4434-4dab-8a0a-712f98478dc9", "text": "Mennyi az 5 : 15 arány legegyszerűbb alakja?", "type": "multiple-choice", "options": [{"id": "f2a98613-2a89-4ac8-abb0-7beb21b186cb", "text": "1 : 3", "isCorrect": true}, {"id": "d63c2057-1525-421e-9327-dd3414c40b02", "text": "1 : 5", "isCorrect": false}, {"id": "58c234cc-f234-40e7-aeff-6ae2eb40649f", "text": "3 : 1", "isCorrect": false}, {"id": "495c36f8-15ba-4eed-b5b1-38747825cbd7", "text": "1 : 2", "isCorrect": false}], "timeLimit": 15}, {"id": "1147841d-b0ba-42b9-8056-582e47bb55be", "text": "Mennyi 200-nak a 3/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120"}, {"id": "4a6cb058-226e-47c3-a48b-25e0f5bb8e5e", "text": "Mi a sorozat 5. eleme: 3, 6, 12, 24, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "48"}, {"id": "bd8f7f95-9e45-42d6-a580-747e4a692124", "text": "Az arányos osztásnál a részek összege kiadja az eredeti egészet.", "type": "true-false", "options": [{"id": "7fbcbc14-2b5c-4b76-bae0-72291726105c", "text": "Igaz", "isCorrect": true}, {"id": "4153cf7a-42ea-4be6-a759-40db25f96f40", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "374d16b4-f106-4669-b35e-54c7f732a94e", "text": "Hány dl szörp kell 2 liter (1:4 arányú) hígított italhoz? (20 dl / 5 = 4 dl)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "7ef1a29c-6787-46f0-b891-05c222a94703", "text": "A játékos versenyzés növeli a feladatmegoldási motivációt.", "type": "true-false", "options": [{"id": "8de73ed3-7c17-464c-8c00-d09a081e615a", "text": "Igaz", "isCorrect": true}, {"id": "b31caff7-716c-4016-b735-135d072ef4d3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('ea11fb83-a1f3-4b7e-ab39-7cd6f66a6033', '21feff02-016d-46e2-bb9d-c27495133b1b', '81. óra: Százalékszámítás', '1 egész = 100%, 1% fogalma (századrész), százalék és törtrész kapcsolata.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "31f1ffd5-7349-4426-a964-bfc5e1737982", "text": "Mit jelent a 1% (egy százalék) fogalma?", "type": "multiple-choice", "options": [{"id": "ded4fdbe-2e69-4c8f-bd0d-3852521ba563", "text": "Az egész mennyiség 1/100-ad részét (századrészét)", "isCorrect": true}, {"id": "dc4c7859-f874-41a4-8277-135e39ee5cc2", "text": "Az egész 1/10-ed részét", "isCorrect": false}, {"id": "e81315c8-8d63-42fb-b6e0-e64be45c5c87", "text": "100 egészet", "isCorrect": false}, {"id": "4a28dc23-fad9-48fc-9d24-b317d69b88d6", "text": "Az egész felét", "isCorrect": false}], "timeLimit": 15}, {"id": "bd5f710b-e3b5-4ee3-bd0d-5bb35531f4a4", "text": "Hány százalék felel meg a teljes egésznek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "316e32cb-83b6-456d-b15e-95bf8364dcdb", "text": "Hány százalék felel meg a fél (1/2) mennyiségnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "5cc7beca-551f-4762-9714-984a1abaedf2", "text": "Hány százalék felel meg a negyed (1/4) mennyiségnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "b84cd37d-2a13-4e71-b863-a89a7feb9f80", "text": "Hány százalék felel meg a háromnegyed (3/4) mennyiségnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "75"}, {"id": "1b122b6e-892a-4168-bebd-a6fd3c84c14e", "text": "A 10% az egész 1/10-ed részét jelenti.", "type": "true-false", "options": [{"id": "66703901-4a0b-4157-b053-ba6840014024", "text": "Igaz", "isCorrect": true}, {"id": "35ef5e4d-2291-4545-8c28-5288f021523c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "03c826d0-b082-4c41-b690-298aea8bd828", "text": "A 20% az egész 1/5-öd részének felel meg.", "type": "true-false", "options": [{"id": "b9400c37-16c7-424d-ba47-8a49abdda849", "text": "Igaz", "isCorrect": true}, {"id": "0109d49c-4ee2-4251-b006-f3b3dbcea018", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());